    fn load_config_with_toml_override() {
        let temp = TempDir::new().unwrap();
        let override_path = temp.path().join("custom.toml");
        fs::write(&override_path, "app_name = \"TomlOverride\"").unwrap();

        let config = load_config(temp.path(), Some(&override_path)).unwrap();
        assert_eq!(config.app_name, Some("TomlOverride".to_string()));
    }

    #[test]
    fn load_config_file_handles_empty_toml() {
        let temp = TempDir::new().unwrap();
        let config_path = temp.path().join("config.toml");
        fs::write(&config_path, "").unwrap();

        let config = load_config_file(&config_path).unwrap();
        assert!(config.app_name.is_none());
        assert!(config.steps.is_empty());
    }
