        path: source_path.to_path_buf(),
        message: e.to_string(),
    })
}

/// Parse TOML content into BivvyConfig.
///
/// # Arguments
///
/// * `content` - The TOML content to parse
/// * `source_path` - Path for error reporting
pub fn parse_toml_config(content: &str, source_path: &Path) -> Result<BivvyConfig> {
    toml::from_str(content).map_err(|e| BivvyError::ConfigParseError {
        path: source_path.to_path_buf(),
        message: e.to_string(),
    })
}

/// Convert a `toml::Value` into a `serde_yaml::Value`.
///
/// This allows TOML-sourced configs to participate in the deep merge
/// pipeline, which operates on `serde_yaml::Value`.
fn toml_value_to_yaml_value(val: toml::Value) -> serde_yaml::Value {
    match val {
        toml::Value::String(s) => serde_yaml::Value::String(s),
        toml::Value::Integer(i) => serde_yaml::Value::Number(i.into()),
        toml::Value::Float(f) => serde_yaml::Value::Number(f.into()),
        toml::Value::Boolean(b) => serde_yaml::Value::Bool(b),
        toml::Value::Datetime(dt) => serde_yaml::Value::String(dt.to_string()),
        toml::Value::Array(arr) => {
            let seq = arr.into_iter().map(toml_value_to_yaml_value).collect();
            serde_yaml::Value::Sequence(seq)
        }
        toml::Value::Table(table) => {
            let mut mapping = serde_yaml::Mapping::new();
            for (k, v) in table {
                mapping.insert(
                    serde_yaml::Value::String(k),
                    toml_value_to_yaml_value(v),
                );
            }
            serde_yaml::Value::Mapping(mapping)
        }
    }
}

/// Load a config file as raw YAML Value (for merging).
///
/// Returns the raw `serde_yaml::Value` without deserializing into
/// `BivvyConfig`, which allows for deep merging before final parsing.
/// Supports both YAML and TOML files.
pub fn load_config_value(path: &Path) -> Result<serde_yaml::Value> {
    let content = read_file(path)?;

    if is_toml(path) {
        let toml_val: toml::Value =
            toml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
                path: path.to_path_buf(),
                message: e.to_string(),
            })?;
        Ok(toml_value_to_yaml_value(toml_val))
    } else {
        serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
            path: path.to_path_buf(),
            message: e.to_string(),
        })
    }
}

