        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();
        fs::write(
            bivvy_dir.join("config.yml"),
            format!(
                r#"
extends:
  - url: {}
app_name: MyApp
steps:
  test:
    command: jest
"#,
                server.url("/base.yml")
            ),
        )
        .unwrap();

        let resolver = resolver_for_mock(&server);
        let config = load_merged_config_with_resolver(temp.path(), &resolver).unwrap();

        // Local app_name is preserved
        assert_eq!(config.app_name, Some("MyApp".to_string()));
        // Base step is merged in
        assert!(config.steps.contains_key("lint"));
        assert_eq!(config.steps["lint"].command, Some("eslint .".to_string()));
        // Local step is preserved
        assert!(config.steps.contains_key("test"));
        // Extends is cleared
        assert!(config.extends.is_none());
    }

    #[test]
    fn extends_merges_before_local_override() {
        let server = MockServer::start();

        let base_yaml = r#"
app_name: BaseApp
settings:
  default_output: quiet
steps:
  install:
    command: npm install
    title: Base install
"#;

        server.mock(|when, then| {
            when.method(GET).path("/base.yml");
            then.status(200).body(base_yaml);
        });

        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();

        // Project config extends base and overrides install command
        fs::write(
            bivvy_dir.join("config.yml"),
            format!(
                r#"
extends:
  - url: {}
app_name: MyApp
steps:
  install:
    command: yarn install
"#,
                server.url("/base.yml")
            ),
        )
        .unwrap();

        let resolver = resolver_for_mock(&server);
        let config = load_merged_config_with_resolver(temp.path(), &resolver).unwrap();

        // Local overrides base
        assert_eq!(config.app_name, Some("MyApp".to_string()));
        assert_eq!(
            config.steps["install"].command,
            Some("yarn install".to_string())
        );
    }

    #[test]
    fn extends_with_local_override_file() {
        let server = MockServer::start();

        let base_yaml = r#"
app_name: BaseApp
steps:
  install:
    command: npm install
"#;

        server.mock(|when, then| {
            when.method(GET).path("/base.yml");
            then.status(200).body(base_yaml);
        });

        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();

        // Project config extends base
        fs::write(
            bivvy_dir.join("config.yml"),
            format!(
                r#"
extends:
  - url: {}
app_name: ProjectApp
"#,
                server.url("/base.yml")
            ),
        )
        .unwrap();

        // Local override file overrides app_name
        fs::write(
            bivvy_dir.join("config.local.yml"),
            "app_name: LocalOverride\n",
        )
        .unwrap();

        let resolver = resolver_for_mock(&server);
        let config = load_merged_config_with_resolver(temp.path(), &resolver).unwrap();

        // The extends resolution happens on the merged config,
        // so local override takes effect before extends
        // But since extends is in config.yml and local overrides app_name,
        // the merged config will have app_name=LocalOverride + extends from config.yml
        assert_eq!(config.app_name, Some("LocalOverride".to_string()));
        // Base step should be present (extends still works)
        assert!(config.steps.contains_key("install"));
    }

    #[test]
    fn config_without_extends_still_works() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();
        fs::write(bivvy_dir.join("config.yml"), "app_name: NoExtends").unwrap();

        // Using default resolver — won't make any HTTP calls
        let config = load_merged_config(temp.path()).unwrap();
        assert_eq!(config.app_name, Some("NoExtends".to_string()));
    }

    // --- TOML configuration support tests ---

    #[test]
    fn discover_finds_toml_project_config() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();
        fs::write(bivvy_dir.join("config.toml"), "app_name = \"test\"").unwrap();

        let paths = ConfigPaths::discover(temp.path());
        assert!(paths.project.is_some());
        assert!(paths.has_project_config());
        assert!(paths.project.unwrap().ends_with("config.toml"));
    }

    #[test]
    fn discover_prefers_yml_over_toml() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();
        fs::write(bivvy_dir.join("config.yml"), "app_name: from-yml").unwrap();
        fs::write(
            bivvy_dir.join("config.toml"),
            "app_name = \"from-toml\"",
        )
        .unwrap();

        let paths = ConfigPaths::discover(temp.path());
        assert!(paths.project.as_ref().unwrap().ends_with("config.yml"));
    }

    #[test]
    fn discover_finds_toml_local_overrides() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();
        fs::write(bivvy_dir.join("config.toml"), "").unwrap();
        fs::write(bivvy_dir.join("config.local.toml"), "").unwrap();

        let paths = ConfigPaths::discover(temp.path());
        assert!(paths.project_local.is_some());
        assert!(
            paths
                .project_local
                .unwrap()
                .ends_with("config.local.toml")
        );
    }

    #[test]
    fn discover_prefers_yml_local_over_toml_local() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();
        fs::write(bivvy_dir.join("config.yml"), "").unwrap();
        fs::write(bivvy_dir.join("config.local.yml"), "").unwrap();
        fs::write(bivvy_dir.join("config.local.toml"), "").unwrap();

        let paths = ConfigPaths::discover(temp.path());
        assert!(
            paths
                .project_local
                .as_ref()
                .unwrap()
                .ends_with("config.local.yml")
        );
    }

    #[test]
    fn load_config_file_parses_valid_toml() {
        let temp = TempDir::new().unwrap();
        let config_path = temp.path().join("config.toml");
        fs::write(&config_path, "app_name = \"TomlApp\"").unwrap();

        let config = load_config_file(&config_path).unwrap();
        assert_eq!(config.app_name, Some("TomlApp".to_string()));
    }

    #[test]
    fn load_config_file_parses_toml_with_steps() {
        let temp = TempDir::new().unwrap();
        let config_path = temp.path().join("config.toml");
        fs::write(
            &config_path,
            r#"
app_name = "FullTomlApp"

[settings]
default_output = "quiet"

[steps.test]
command = "echo test"

[workflows.default]
steps = ["test"]
"#,
        )
        .unwrap();

        let config = load_config_file(&config_path).unwrap();
        assert_eq!(config.app_name, Some("FullTomlApp".to_string()));
        assert!(config.steps.contains_key("test"));
        assert_eq!(
            config.steps["test"].command,
            Some("echo test".to_string())
        );
        assert!(config.workflows.contains_key("default"));
    }

    #[test]
    fn load_config_value_parses_toml() {
        let temp = TempDir::new().unwrap();
        let config_path = temp.path().join("config.toml");
        fs::write(
            &config_path,
            "key = \"value\"\n\n[nested]\ninner = 42",
        )
        .unwrap();

        let value = load_config_value(&config_path).unwrap();
        assert_eq!(value["key"], "value");
        assert_eq!(value["nested"]["inner"], 42);
    }

    #[test]
    fn parse_toml_config_returns_parse_error_for_invalid_toml() {
        let content = "invalid = [toml";
        let result = parse_toml_config(content, Path::new("test.toml"));
        assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
    }

    #[test]
    fn load_merged_config_works_with_toml_project_config() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();

        fs::write(
            bivvy_dir.join("config.toml"),
            r#"
app_name = "TomlProject"

[steps.test]
command = "echo test"
"#,
        )
        .unwrap();

        let config = load_merged_config(temp.path()).unwrap();
        assert_eq!(config.app_name, Some("TomlProject".to_string()));
        assert!(config.steps.contains_key("test"));
    }

    #[test]
    fn load_merged_config_mixes_yml_project_and_toml_local() {
        use crate::config::schema::OutputMode;

        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();

        // YAML project config
        fs::write(
            bivvy_dir.join("config.yml"),
            r#"
app_name: YmlApp
settings:
  default_output: verbose
steps:
  test:
    command: "echo yml"
"#,
        )
        .unwrap();

        // TOML local override
        fs::write(
            bivvy_dir.join("config.local.toml"),
            r#"
[settings]
default_output = "quiet"
"#,
        )
        .unwrap();

        let config = load_merged_config(temp.path()).unwrap();
        assert_eq!(config.app_name, Some("YmlApp".to_string()));
        assert_eq!(config.settings.default_output, OutputMode::Quiet);
        assert!(config.steps.contains_key("test"));
    }

    #[test]
    fn load_config_with_toml_override() {
        let temp = TempDir::new().unwrap();
        let override_path = temp.path().join("custom.toml");
        fs::write(&override_path, "app_name = \"TomlOverride\"").unwrap();

        let config = load_config(temp.path(), Some(&override_path)).unwrap();
        assert_eq!(config.app_name, Some("TomlOverride".to_string()));
    }

    #[test]
    fn load_config_file_handles_empty_toml() {
        let temp = TempDir::new().unwrap();
        let config_path = temp.path().join("config.toml");
        fs::write(&config_path, "").unwrap();

        let config = load_config_file(&config_path).unwrap();
        assert!(config.app_name.is_none());
        assert!(config.steps.is_empty());
    }
